    assert.strictEqual(bytes('100kb'), 102400);
    assert.strictEqual(bytes('+100kb'), 102400);
    assert.strictEqual(bytes('-100kb'), -102400);

    // The change removes ^, which should make the regex less strict
    // But the original behavior should still hold for valid inputs
    // Let's test a case that might be affected: string with leading whitespace
    assert.strictEqual(bytes('  100kb'), 102400);

